class Solution { vector<int> distances(vector<int>& edges,int node){vector<int> distance(edges.size(),-1);for(int steps=0;node!=-1&&distance[node]==-1;++steps){distance[node]=steps;node=edges[node];}return distance;}public:int closestMeetingNode(vector<int>& edges,int node1,int node2){auto first=distances(edges,node1),second=distances(edges,node2);int answer=-1,best=INT_MAX;for(int i=0;i<(int)edges.size();++i)if(first[i]>=0&&second[i]>=0&&max(first[i],second[i])<best){best=max(first[i],second[i]);answer=i;}return answer;} };
